/* Local optional rear design preview; shared front background, no order mutation. */
function tintRearPixels(data,background){
 if(!/^#[0-9a-f]{6}$/i.test(background))throw Error('Geçerli ambalaj rengi bulunamadı.');
 if(background.toLowerCase()==='#ffffff')return data;
 const rgb=background.match(/[0-9a-f]{2}/gi).map(v=>parseInt(v,16));
 for(let i=0;i<data.length;i+=4){if(!data[i+3])continue;const lum=(.2126*data[i]+.7152*data[i+1]+.0722*data[i+2])/255,color=materialColor(rgb,lum);data[i]=color[0];data[i+1]=color[1];data[i+2]=color[2];}return data;
}
function rearPackageClip(context,w,h){const points=[[3.2,7.4],[9.1,13.5],[12.3,15.2],[21,15.4],[33,16],[46,14.8],[57,14.8],[69,14.5],[83,14.3],[88.7,15.9],[91,12.2],[97,7.4],[97,93.5],[91,90],[89.5,88.9],[88.6,89.9],[86.7,88.4],[83,88.3],[70,87.5],[56,87],[45,86.8],[33,88.3],[20,88.4],[11.5,88.1],[9.1,90.4],[3.2,93.5]];context.beginPath();points.forEach((p,i)=>i?context.lineTo(p[0]*w/100,p[1]*h/100):context.moveTo(p[0]*w/100,p[1]*h/100));context.closePath();context.clip();}
function rearMaterialDataURL(source,background){const c=document.createElement('canvas');c.width=source.naturalWidth;c.height=source.naturalHeight;const context=c.getContext('2d',{willReadFrequently:true});context.save();rearPackageClip(context,c.width,c.height);context.drawImage(source,0,0);context.restore();if(background.toLowerCase()!=='#ffffff'){const pixels=context.getImageData(0,0,c.width,c.height);tintRearPixels(pixels.data,background);context.putImageData(pixels,0,0);}if(rearHasContent()){const qr=rearContent.qrEnabled?QRPreview.encodeUrl(rearContent.qrUrl):null;RearLayout.render(context,c.width,c.height,rearContent,{sponsorImage:rearSponsorImage,qrMatrix:qr?.modules||null,background,inkColor:effectiveRearInkColor()});}const url=c.toDataURL('image/png');c.width=c.height=1;if(!url.startsWith('data:image/png'))throw Error('Arka yüz önizlemesi hazırlanamadı.');return url;}
const rearContent={instagram:'',website:'',phone:'',address:'',extra:'',inkColor:'',qrEnabled:false,qrUrl:'',sponsorName:'',sponsorHash:''};
let rearRevision=0,rearSponsorImage=null,rearSponsorOperation=0,rearSponsorPending=false,rearRenderTimer=null,rearRenderedRevision=-1,rearRenderedData=null;
function effectiveRearInkColor(){if(/^#[0-9a-f]{6}$/i.test(rearContent.inkColor))return rearContent.inkColor;if(state.recolor&&state.recolorApplied&&/^#[0-9a-f]{6}$/i.test(state.color))return state.color;return null;}
function rearHasContent(){return !!(rearContent.instagram.trim()||rearContent.website.trim()||rearContent.phone.trim()||rearContent.address.trim()||rearContent.extra.trim()||rearContent.sponsorHash||rearContent.qrEnabled);}
function rearQuoteSnapshot(){return {revision:rearRevision,instagram:rearContent.instagram.trim(),website:rearContent.website.trim(),phone:rearContent.phone.trim(),address:rearContent.address.trim(),extra:rearContent.extra.trim(),inkColor:effectiveRearInkColor(),sponsorHash:rearContent.sponsorHash||null,qr:rearContent.qrEnabled?{enabled:true,url:rearContent.qrUrl.trim()}:null};}
function rearQuoteReady(){return !rearHasContent()||(!rearSponsorPending&&rearPreviewReady&&rearRenderedRevision===rearRevision&&!!rearRenderedData);}
function rearQuoteImage(){return rearHasContent()&&rearQuoteReady()?rearRenderedData:null;}
function rearValidationError(){if(rearSponsorPending)return 'Sponsor logosu yükleniyor; lütfen bekleyin.';if(rearContent.qrEnabled){if(!rearContent.qrUrl.trim())return 'QR kod için menü veya bağlantı adresini yazın.';try{QRPreview.encodeUrl(rearContent.qrUrl);}catch(e){return e.message;}}return '';}
function clearRearContent(){rearSponsorOperation++;rearSponsorPending=false;rearSponsorImage=null;Object.assign(rearContent,{instagram:'',website:'',phone:'',address:'',extra:'',inkColor:'',qrEnabled:false,qrUrl:'',sponsorName:'',sponsorHash:''});rearRevision++;rearRenderedData=null;rearRenderedRevision=-1;clearTimeout(rearRenderTimer);if($('rearInstagram'))syncRearFields();}
function rearChanged(){rearRevision++;rearRenderedData=null;rearRenderedRevision=-1;rearPreviewReady=false;invalidateQuote();latest=null;$('rearToPrice').disabled=true;clearTimeout(rearRenderTimer);rearRenderTimer=setTimeout(()=>{if(!rearPreview.hidden)renderRearPreview(false);},180);}
let rearPreviewGeneration=0,rearPreviewFingerprint=null,rearPreviewReady=false;
const rearPreview=document.createElement('section');rearPreview.id='rearPreview';rearPreview.hidden=true;
rearPreview.innerHTML='<h1 id="rearTitle" tabindex="-1">Arka yüz</h1><p class="subtitle">Ön yüzü onayladınız. Aynı zemin rengindeki arka yüzü aşağıdan düzenleyebilirsiniz.</p><div class="rearFlipScene"><div id="rearFlipCard" class="rearFlipCard"><div class="rearFlipFace rearFlipFront" aria-hidden="true"><img id="rearFrontImage" alt=""></div><div class="rearFlipFace rearFlipBack"><img id="rearBlankImage" alt="Boş arka ambalaj; ortadaki yapıştırma dikişi görünür"></div></div></div><p id="rearAssetError" role="alert" hidden>Arka yüz görseli yüklenemedi. <button id="retryRearAsset" class="outline" type="button">Yeniden dene</button></p><div id="rearEditor" class="rearEditor"><h2>Arka yüze ne ekleyelim?</h2><p class="hint">Hepsi isteğe bağlı. İstemediğiniz alanı boş bırakın.</p><div class="rearFieldGrid"><label>Instagram<input id="rearInstagram" type="text" maxlength="80" placeholder="@isletmeniz"></label><label>Web sitesi<input id="rearWebsite" type="text" maxlength="140" placeholder="www.ornek.com"></label><label>Telefon<input id="rearPhone" type="tel" maxlength="50" placeholder="+90 …"></label><label>Adres<input id="rearAddress" type="text" maxlength="220" placeholder="İsteğe bağlı adres"></label></div><details class="rearOptional"><summary>Ek yazı ve yazı rengi</summary><label>Ek yazı / slogan<input id="rearExtra" type="text" maxlength="140" placeholder="İsteğe bağlı işletme adı veya kısa slogan"></label><label>Arka yüz yazı rengi<select id="rearInkColor"><option value="">Ön yüzle uyumlu / otomatik</option><option value="#111111">Siyah</option><option value="#ffffff">Beyaz</option><option value="#102f59">Lacivert</option><option value="#800d2e">Bordo</option><option value="#245b47">Yeşil</option><option value="#b58a43">Altın tonu</option><option value="#edb9a1">Şeftali tonu</option></select></label><p class="hint">Bu ekran rengi önizlemesidir; Pantone veya baskı renk garantisi değildir.</p></details><details class="rearOptional"><summary>Sponsor logosu ekle</summary><p class="hint">Başka bir firmanın temiz logosunu ekleyebilirsiniz. Şeffaf PNG veya SVG önerilir.</p><input id="rearSponsorUpload" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"><span id="rearSponsorName"></span><button id="removeRearSponsor" class="outline" type="button" hidden>Logoyu kaldır</button></details><label class="rearQrToggle"><input id="rearQrEnabled" type="checkbox"> QR kod ekle <small>(isteğe bağlı)</small></label><div id="rearQrFields" hidden><label>QR bağlantısı<input id="rearQrUrl" type="url" maxlength="512" placeholder="https://… menü, site veya sosyal medya bağlantısı"></label><div class="rearQuickLinks"><button id="rearQrWebsite" class="textButton" type="button">Web sitesini kullan</button><button id="rearQrInstagram" class="textButton" type="button">Instagram adresini kullan</button></div><p class="hint">QR kod cihazınızda oluşturulur. Baskıdan önce boyut ve telefonla okunurluk kontrol edilir.</p></div><p id="rearEditorError" class="actionHelp" role="alert" hidden></p><p id="rearPriceNote" class="notice light" hidden>Arka yüz içeriği eklendi. Ön ve arka yüzün toplam baskı renkleri/klişesi teknik incelemede netleşir; gösterilen ara toplam klişe bedelini içermez.</p></div><div class="rearActions"><button id="backToFront" class="outline" type="button">← Ön yüze dön</button><button id="rearToPrice" class="primary" type="button">Arka yüzü onayla ve fiyatı gör</button></div>';
$('design').after(rearPreview);
function resetRearPreview(){clearRearContent();rearPreviewGeneration++;rearPreviewFingerprint=null;rearPreviewReady=false;rearPreview.hidden=true;$('rearFlipCard').classList.remove('is-flipped');$('rearFrontImage').removeAttribute('src');if(step===4){step=1;$('design').hidden=false;}}
function hideRearPreview(){rearPreviewGeneration++;rearPreview.hidden=true;}
function showRearPreview(){
 if(designIssue()||state.designProcessing||!(state.logo||state.photoLayout)||!processingSession.isApproved(designFingerprint())){showDesignIssue();return false;}
 rearPreviewFingerprint=designFingerprint();const front=imageData();
 ['design','pricing','summary','photoEditor','pdfPicker','whiteCarrierPanel'].forEach(id=>{if($(id))$(id).hidden=true;});step=4;rearPreview.hidden=false;$('simpleTools').hidden=true;$('simpleDetails').hidden=true;
 $('rearFlipCard').classList.remove('is-flipped');$('rearFrontImage').src=front;syncRearFields();renderRearPreview(true);
 $('rearTitle').focus({preventScroll:true});status('Ön yüz onaylandı. Arka yüzdeki alanlar isteğe bağlıdır.');window.scrollTo({top:0,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return true;
}
function renderRearPreview(flip){
 const generation=++rearPreviewGeneration,revision=rearRevision,background=state.bg;rearPreviewReady=false;$('rearToPrice').disabled=true;$('rearAssetError').hidden=true;$('rearEditorError').hidden=true;$('rearPriceNote').hidden=!rearHasContent();
 const error=rearValidationError();if(error){$('rearEditorError').textContent=error;$('rearEditorError').hidden=false;return;}
 const rear=$('rearBlankImage'),current=()=>generation===rearPreviewGeneration&&revision===rearRevision&&!rearPreview.hidden&&rearPreviewFingerprint===designFingerprint();
 rear.onload=()=>{if(!current())return;if(!rear.naturalWidth){rear.onerror();return;}rearPreviewReady=true;rearRenderedRevision=revision;rearRenderedData=rear.src;$('rearToPrice').disabled=false;requestAnimationFrame(()=>requestAnimationFrame(()=>{if(current())$('rearFlipCard').classList.add('is-flipped');}));};
 rear.onerror=()=>{if(!current())return;rearPreviewReady=false;$('rearToPrice').disabled=true;$('rearAssetError').hidden=false;};
 const source=new Image();source.onload=()=>{if(!current())return;try{rear.src=rearMaterialDataURL(source,background);}catch(error){rearPreviewReady=false;$('rearToPrice').disabled=true;$('rearEditorError').textContent=error.message||'Arka yüz hazırlanamadı.';$('rearEditorError').hidden=false;}};source.onerror=()=>{if(current())rear.onerror();};source.src='assets/bm12-back-blank.png';
}
function syncRearFields(){for(const [id,key]of [['rearInstagram','instagram'],['rearWebsite','website'],['rearPhone','phone'],['rearAddress','address'],['rearExtra','extra'],['rearInkColor','inkColor'],['rearQrUrl','qrUrl']])$(id).value=rearContent[key];$('rearQrEnabled').checked=rearContent.qrEnabled;$('rearQrFields').hidden=!rearContent.qrEnabled;$('rearSponsorName').textContent=rearContent.sponsorName;$('removeRearSponsor').hidden=!rearContent.sponsorHash;}
for(const [id,key]of [['rearInstagram','instagram'],['rearWebsite','website'],['rearPhone','phone'],['rearAddress','address'],['rearExtra','extra'],['rearInkColor','inkColor'],['rearQrUrl','qrUrl']])$(id).oninput=()=>{rearContent[key]=$(id).value;rearChanged();};
$('rearQrEnabled').onchange=()=>{rearContent.qrEnabled=$('rearQrEnabled').checked;if(!rearContent.qrEnabled)rearContent.qrUrl='';syncRearFields();rearChanged();};
$('rearQrWebsite').onclick=()=>{const value=rearContent.website.trim();if(!value){$('rearEditorError').textContent='Önce web sitesi alanını doldurun.';$('rearEditorError').hidden=false;return;}rearContent.qrUrl=/^https?:\/\//i.test(value)?value:'https://'+value;syncRearFields();rearChanged();};
$('rearQrInstagram').onclick=()=>{const value=rearContent.instagram.trim();if(!value){$('rearEditorError').textContent='Önce Instagram adresini yazın.';$('rearEditorError').hidden=false;return;}rearContent.qrUrl=/^https?:\/\//i.test(value)?value:'https://www.instagram.com/'+value.replace(/^@/,'')+'/';syncRearFields();rearChanged();};
$('removeRearSponsor').onclick=()=>{rearSponsorOperation++;rearSponsorPending=false;rearSponsorImage=null;rearContent.sponsorHash='';rearContent.sponsorName='';syncRearFields();rearChanged();};
$('rearSponsorUpload').onchange=async e=>{const file=e.target.files[0];if(!file)return;const operation=++rearSponsorOperation;rearSponsorImage=null;rearContent.sponsorHash='';rearContent.sponsorName='';rearSponsorPending=true;syncRearFields();rearChanged();try{if(file.size>UploadFormat.MAX_BYTES)throw Error('Logo en fazla 8 MB olmalı.');const bytes=await file.arrayBuffer(),info=UploadFormat.inspect(new Uint8Array(bytes));if(!['image/png','image/jpeg','image/webp','image/svg+xml'].includes(info.mime))throw Error('Sponsor logosunu PNG, JPG, WebP veya SVG olarak yükleyin.');let data;if(info.mime==='image/svg+xml')data=svgSafe(await file.text()).data;else data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Logo okunamadı.'));reader.readAsDataURL(file);});const image=await loadImage(data),identity=await sourceIdentity(file,bytes);if(operation!==rearSponsorOperation)return;rearSponsorImage=image;rearContent.sponsorHash=identity.sha256;rearContent.sponsorName=file.name;rearSponsorPending=false;syncRearFields();rearChanged();}catch(error){if(operation!==rearSponsorOperation)return;rearSponsorPending=false;$('rearEditorError').textContent=error.message||'Logo açılamadı.';$('rearEditorError').hidden=false;rearPreviewReady=false;$('rearToPrice').disabled=true;}finally{e.target.value='';}};
$('backToFront').onclick=()=>go(1);
$('retryRearAsset').onclick=()=>showRearPreview();
$('rearToPrice').onclick=()=>{
 if(rearValidationError()){ $('rearEditorError').textContent=rearValidationError();$('rearEditorError').hidden=false;return;}if(!rearQuoteReady()||!rearPreviewReady||rearPreviewFingerprint!==designFingerprint()||!processingSession.isApproved(designFingerprint())||designIssue()){go(1);status('Ön yüz değişti. Yeniden kontrol edip onaylayın.');return;}
 go(2);
};
